// Scaffold generated by craftgo. Safe to edit; will not be overwritten.
//
// Boots the runtime server using the loaded `*config.Config` as the
// single source of truth. Traces and metrics are set up together by
// [telemetry.Init], which keeps the exporter selection (none / stdout /
// otlp_grpc / otlp_http / prometheus) next to the SDK rather than inline
// here, and gives both signals one `serviceName`, one gRPC handler and
// one Shutdown. The only knob exposed to the deployer is `config.yaml`
// (see config/example.config.yaml for the full field reference).

package main

import (
	"context"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/craftgodotdev/craftgo/pkg/log"
	"github.com/craftgodotdev/craftgo/pkg/rpc"
	"github.com/craftgodotdev/craftgo/pkg/telemetry"

	"example.com/app/config"
	"example.com/app/internal/wiring"
	"example.com/app/svccontext"
)

func main() {
	cfg, err := config.Load(config.Path())
	if err != nil {
		log.Default().Error("load config", log.Err(err))
		os.Exit(1)
	}

	// config.logging.level retunes the shared logger for both the server
	// and the generated logic layer. An unrecognised value keeps the
	// info default.
	if lvl, ok := log.ParseLevel(cfg.Logging.Level); ok {
		log.SetLevel(lvl)
	}

	ctx := context.Background()

	// Both signals share `serviceName`, one gRPC handler and one Shutdown.
	tel, err := telemetry.Init(ctx, cfg.Config)
	if err != nil {
		log.Default().Error("init telemetry", log.Err(err))
		os.Exit(1)
	}
	if url := tel.ScrapeURL(); url != "" {
		log.Default().Info("metrics scrape listening", log.String("url", url))
	}
	if errCh := tel.AdminErr(); errCh != nil {
		go func() {
			if err := <-errCh; err != nil {
				log.Default().Error("metrics scrape listener", log.Err(err))
			}
		}()
	}

	svc := svccontext.NewServiceContext(cfg)

	// The gRPC listener takes the guards the HTTP chain takes, in the same
	// order: the OTel stats handler opens the span in the transport, ahead
	// of every interceptor, so AccessLog sees the trace ids on ctx, and the
	// same handler records `rpc.server.call.duration` against the
	// configured MeterProvider. Recovery is always outermost. Errors are
	// mapped onto status codes where the generated server layer returns
	// them (rpc.Error), as WriteError does for HTTP.
	grpcSrv := rpc.New(svc,
		rpc.WithStatsHandler(tel.GRPCServerHandler()),
		rpc.WithReflection(cfg.GRPC.Reflection),
	)
	grpcSrv.Use(rpc.AccessLog(grpcSrv.Logger()))
	// The default deadline for unary calls; a shorter client deadline
	// still wins, and streams are not bounded.
	grpcSrv.Use(rpc.Timeout(cfg.GRPC.HandlerTimeout))

	// One call attaches every gRPC service the protos declare. The wiring
	// package is regenerated on each `craftgo gen`, so this line stays put
	// when the design gains or loses one. The returned shutdown runs
	// beside grpcSrv.Stop below.
	shutdownGRPC, err := wiring.RegisterGRPC(ctx, grpcSrv, svc)
	if err != nil {
		log.Default().Error("wire grpc services", log.Err(err))
		os.Exit(1)
	}

	go func() {
		log.Default().Info("grpc listening", log.String("addr", cfg.GRPC.Addr))
		if err := grpcSrv.Start(cfg.GRPC.Addr); err != nil {
			log.Default().Error("grpc server start", log.Err(err))
			os.Exit(1)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	// In-flight RPCs finish within the same budget; whatever is still
	// running when it runs out is cut off.
	_ = grpcSrv.Stop(shutdownCtx)
	_ = shutdownGRPC(shutdownCtx)
	// Closes the scrape listener and drains any pending OTLP push batch.
	if err := tel.Shutdown(shutdownCtx); err != nil {
		log.Default().Error("shutdown telemetry", log.Err(err))
	}
}
